package com.example.productinventory.model;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false) private String description; @Column(nullable=false,precision=19,scale=2) private BigDecimal price; @Column(nullable=false) private Integer quantity; @Column(nullable=false) private String category; protected Product(){} public Product(String n,String d,BigDecimal p,Integer q,String c){name=n;description=d;price=p;quantity=q;category=c;} public Long getId(){return id;} public String getName(){return name;} public String getDescription(){return description;} public BigDecimal getPrice(){return price;} public Integer getQuantity(){return quantity;} public String getCategory(){return category;} public void update(String n,String d,BigDecimal p,Integer q,String c){name=n;description=d;price=p;quantity=q;category=c;} }